package com.suresh.lifeos;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.graphics.Color;import android.hardware.biometrics.BiometricPrompt;import android.net.Uri;import android.os.*;import android.provider.CalendarContract;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.concurrent.Executor;

public class MainActivity extends Activity{
 static final int BG=Color.rgb(9,17,31),CARD=Color.rgb(17,28,47),TEXT=Color.rgb(239,246,255),MUTED=Color.rgb(157,173,194),ACC=Color.rgb(72,213,151),WARN=Color.rgb(255,184,77); Store s; boolean unlocked=false; String backupPassword=""; static final int SAVE=701,OPEN=702;
 @Override public void onCreate(Bundle b){super.onCreate(b);s=Store.get(this);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);requestBasics();showLock();}
 void requestBasics(){ArrayList<String> p=new ArrayList<>();if(checkSelfPermission(Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.READ_CALENDAR);if(checkSelfPermission(Manifest.permission.WRITE_CALENDAR)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.WRITE_CALENDAR);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.POST_NOTIFICATIONS);if(!p.isEmpty())requestPermissions(p.toArray(new String[0]),99);}
 TextView t(String x,int z,boolean bold){TextView v=new TextView(this);v.setText(x);v.setTextColor(TEXT);v.setTextSize(z);v.setPadding(10,8,10,8);if(bold)v.setTypeface(null,1);return v;} TextView sub(String x){TextView v=t(x,13,false);v.setTextColor(MUTED);return v;}
 Button btn(String x){Button b=new Button(this);b.setText(x);b.setTextColor(Color.BLACK);b.setBackgroundColor(ACC);b.setAllCaps(false);return b;} Button dark(String x){Button b=btn(x);b.setTextColor(TEXT);b.setBackgroundColor(Color.rgb(35,48,68));return b;}
 LinearLayout base(String title,String subtitle){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(18,18,18,50);x.setBackgroundColor(BG);x.addView(t(title,26,true));if(subtitle!=null)x.addView(sub(subtitle));return x;} ScrollView scroll(LinearLayout x){ScrollView sv=new ScrollView(this);sv.setFillViewport(true);sv.addView(x);return sv;} LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(14,12,14,12);android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(CARD);g.setCornerRadius(22);c.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);c.setLayoutParams(p);return c;}
 EditText e(String hint){EditText e=new EditText(this);e.setHint(hint);e.setHintTextColor(MUTED);e.setTextColor(TEXT);e.setSingleLine(false);e.setPadding(10,10,10,10);return e;}
 void showLock(){String h=s.get("pin_hash","");LinearLayout x=base("SURESH LIFE OS","Healthier • Stronger • Wealthier • Happier • Together");x.setGravity(Gravity.CENTER_HORIZONTAL);x.addView(t(h.isEmpty()?"Create your private PIN":"Private Life OS — unlock to continue",18,true));EditText p=e(h.isEmpty()?"Create 4–8 digit PIN":"Enter PIN");p.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);x.addView(p);Button go=btn(h.isEmpty()?"Create PIN":"Unlock");x.addView(go);go.setOnClickListener(v->{String q=p.getText().toString();if(q.length()<4||q.length()>8){toast("Use 4–8 digits");return;}if(h.isEmpty()){s.set("pin_hash",sha(q));unlocked=true;home();}else if(sha(q).equals(h)){unlocked=true;home();}else toast("Wrong PIN");});if(!h.isEmpty()&&Build.VERSION.SDK_INT>=28){Button bio=dark("Unlock with fingerprint");x.addView(bio);bio.setOnClickListener(v->fingerprint());}setContentView(scroll(x));}
 void fingerprint(){try{Executor ex=getMainExecutor();BiometricPrompt p=new BiometricPrompt.Builder(this).setTitle("Unlock Suresh Life OS").setSubtitle("Use fingerprint to view private information").setNegativeButton("Use PIN",ex,(d,w)->{}).build();p.authenticate(new android.os.CancellationSignal(),ex,new BiometricPrompt.AuthenticationCallback(){public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){unlocked=true;home();}public void onAuthenticationError(int c,CharSequence m){toast(m.toString());}});}catch(Exception z){toast("Fingerprint unlock is not available. Use PIN.");}}
 String sha(String x){try{byte[]b=MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8));StringBuilder q=new StringBuilder();for(byte y:b)q.append(String.format("%02x",y));return q.toString();}catch(Exception z){return x;}}
 void home(){LinearLayout x=base("SURESH LIFE OS","Your day. Your health. Your family. Your future.");String name=s.get("profile_name","Suresh");x.addView(t("Good day, "+name,19,true));LinearLayout c=card();c.addView(sub("TODAY — "+LocalDate.now()));int total=todayScore();TextView sc=t(total+" Life Points",24,true);sc.setTextColor(ACC);c.addView(sc);c.addView(sub("Never zero. A difficult day can still be a successful day."));x.addView(c);String[][] items={{"TODAY","Today plan & task actions"},{"SCHEDULE","Edit alarms, school, family and work blocks"},{"HEALTH","Weight, waist, glucose, BP and lab history"},{"MEDICATIONS","Private medicine list and timing"},{"MEALS","Recipes, coffee settings and shopping"},{"WORKOUTS","Cycling, MAX:30 safety and strength training"},{"MEMORIES","Family memory book"},{"WORK & MONEY","Projects, income and expenses"},{"REWARDS","Points, penalties and Family Memory Fund"},{"CALENDAR","Google/device Calendar sync"},{"BACKUP","Encrypted Google Drive / Files backup"},{"SETTINGS","Profile, targets, privacy and verification"}};for(String[]it:items){Button b=dark(it[0]+"\n"+it[1]);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);x.addView(b);String k=it[0];b.setOnClickListener(v->route(k));}setContentView(scroll(x));AlarmReceiver.scheduleToday(this);}
 void route(String k){switch(k){case"TODAY":today();break;case"SCHEDULE":tasks();break;case"HEALTH":health();break;case"MEDICATIONS":meds();break;case"MEALS":meals();break;case"WORKOUTS":workouts();break;case"MEMORIES":memories();break;case"WORK & MONEY":workMoney();break;case"REWARDS":rewards();break;case"CALENDAR":calendar();break;case"BACKUP":backup();break;default:settings();}}
 void header(LinearLayout x){Button b=dark("← Dashboard");b.setOnClickListener(v->home());x.addView(b,0);}
 int dow(){return LocalDate.now().getDayOfWeek().getValue();} boolean dayMatch(String ds){return ds!=null&&Arrays.asList(ds.split(",")).contains(String.valueOf(dow()));} String hm(String m){try{int n=Integer.parseInt(m);return String.format(Locale.US,"%02d:%02d",n/60,n%60);}catch(Exception e){return "--:--";}}
 int todayScore(){int total=0;String d=LocalDate.now().toString();for(Map<String,String>m:s.q("SELECT l.status,t.points FROM task_log l JOIN tasks t ON l.task_id=t.id WHERE l.day=?",d))if("DONE".equals(m.get("status")))try{total+=Integer.parseInt(m.get("points"));}catch(Exception ignored){}return total;}
 void today(){LinearLayout x=base("TODAY","Private task details are only shown after unlock.");header(x);List<Map<String,String>>ls=s.q("SELECT * FROM tasks WHERE active=1 ORDER BY start_min");boolean any=false;for(Map<String,String>m:ls){if(!dayMatch(m.get("days")))continue;any=true;LinearLayout c=card();long id=Long.parseLong(m.get("id"));c.addView(t(hm(m.get("start_min"))+"  "+m.get("title"),17,true));c.addView(sub(m.get("category")+" • "+m.get("duration")+" min • +"+m.get("points")+" points"));String st="PENDING";List<Map<String,String>>log=s.q("SELECT status FROM task_log WHERE day=? AND task_id=?",LocalDate.now().toString(),String.valueOf(id));if(!log.isEmpty())st=log.get(0).get("status");c.addView(sub("Status: "+st));LinearLayout row=new LinearLayout(this);Button done=btn("DONE");Button sno=dark("SNOOZE 10");Button cant=dark("I CANNOT");row.addView(done,new LinearLayout.LayoutParams(0,-2,1));row.addView(sno,new LinearLayout.LayoutParams(0,-2,1));row.addView(cant,new LinearLayout.LayoutParams(0,-2,1));c.addView(row);done.setOnClickListener(v->{s.logTask(id,"DONE","");today();});sno.setOnClickListener(v->{snooze(id,10);toast("Snoozed 10 minutes");});cant.setOnClickListener(v->cannot(id,m));x.addView(c);}if(!any)x.addView(sub("No tasks scheduled for today. Add them in Schedule."));setContentView(scroll(x));}
 void snooze(long id,int min){Intent i=new Intent(this,AlarmReceiver.class).putExtra("task_id",id);PendingIntent p=PendingIntent.getBroadcast(this,(int)(100000+id),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)getSystemService(ALARM_SERVICE)).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+min*60000L,p);}
 void cannot(long id,Map<String,String>task){final String[]r={"Emergency","Sick / unwell","Family emergency","Schedule conflict","I avoided it","Other"};new AlertDialog.Builder(this).setTitle("Why can't you do this?").setItems(r,(d,w)->{String reason=r[w];s.logTask(id,"MISSED",reason);if("I avoided it".equals(reason)){int a=100;try{a=Integer.parseInt(task.get("penalty"));}catch(Exception ignored){}addPenalty(reason+": "+task.get("title"),a);}today();}).show();}
 int penaltiesToday(){int n=0;for(Map<String,String>m:s.q("SELECT amount FROM penalties WHERE day=?",LocalDate.now().toString()))try{n+=Integer.parseInt(m.get("amount"));}catch(Exception ignored){}return n;} int penaltiesWeek(){LocalDate st=LocalDate.now().with(java.time.DayOfWeek.MONDAY);int n=0;for(Map<String,String>m:s.q("SELECT amount FROM penalties WHERE day>=?",st.toString()))try{n+=Integer.parseInt(m.get("amount"));}catch(Exception ignored){}return n;}
 void addPenalty(String why,int amount){int dc=parseInt(s.get("daily_penalty_cap","500"),500),wc=parseInt(s.get("weekly_penalty_cap","2000"),2000);amount=Math.max(0,Math.min(amount,Math.min(dc-penaltiesToday(),wc-penaltiesWeek())));if(amount<=0)return;ContentValues v=new ContentValues();v.put("day",LocalDate.now().toString());v.put("reason",why);v.put("amount",amount);s.insert("penalties",v);toast("Rs "+amount+" moved to Family Memory Fund");}
 void tasks(){LinearLayout x=base("SCHEDULE","Everything is editable. Times are never hard-coded permanently.");header(x);Button add=btn("+ Add task / alarm");x.addView(add);add.setOnClickListener(v->editTask(null));for(Map<String,String>m:s.q("SELECT * FROM tasks ORDER BY start_min")){LinearLayout c=card();c.addView(t(hm(m.get("start_min"))+"  "+m.get("title"),16,true));c.addView(sub("Days "+m.get("days")+" • "+m.get("category")+" • "+m.get("privacy")+" • Penalty Rs "+m.get("penalty")));Button ed=dark("Edit");Button de=dark("Delete");c.addView(ed);c.addView(de);ed.setOnClickListener(v->editTask(m));de.setOnClickListener(v->{s.del("tasks",Long.parseLong(m.get("id")));tasks();});x.addView(c);}setContentView(scroll(x));}
 int minFrom(String h){try{String[]a=h.trim().split(":");return Integer.parseInt(a[0])*60+Integer.parseInt(a[1]);}catch(Exception e){return 0;}}
 void editTask(Map<String,String>m){LinearLayout b=base(m==null?"Add task":"Edit task",null);EditText title=e("Title"),cat=e("Category"),days=e("Days: 1,2,3,4,5,6,7"),time=e("Start HH:MM"),dur=e("Duration minutes"),priv=e("Privacy: PRIVATE / SECRET / PUBLIC"),pts=e("Points"),pen=e("Penalty Rs"),notes=e("Notes");CheckBox cal=new CheckBox(this);cal.setText("Sync this task to selected calendar");cal.setTextColor(TEXT);if(m!=null){title.setText(m.get("title"));cat.setText(m.get("category"));days.setText(m.get("days"));time.setText(hm(m.get("start_min")));dur.setText(m.get("duration"));priv.setText(m.get("privacy"));pts.setText(m.get("points"));pen.setText(m.get("penalty"));notes.setText(m.get("notes"));cal.setChecked("1".equals(m.get("calendar_sync")));}else{days.setText("1,2,3,4,5");priv.setText("PRIVATE");pts.setText("5");pen.setText("100");dur.setText("30");}for(View v:new View[]{title,cat,days,time,dur,priv,pts,pen,notes,cal})b.addView(v);new AlertDialog.Builder(this).setTitle(m==null?"Add task":"Edit task").setView(scroll(b)).setPositiveButton("Save",(d,w)->{ContentValues v=new ContentValues();v.put("title",title.getText().toString());v.put("category",cat.getText().toString());v.put("days",days.getText().toString());v.put("start_min",minFrom(time.getText().toString()));v.put("duration",parseInt(dur.getText().toString(),30));v.put("privacy",priv.getText().toString().toUpperCase(Locale.ROOT));v.put("points",parseInt(pts.getText().toString(),5));v.put("penalty",parseInt(pen.getText().toString(),100));v.put("notes",notes.getText().toString());v.put("calendar_sync",cal.isChecked()?1:0);if(m==null)s.insert("tasks",v);else s.update("tasks",Long.parseLong(m.get("id")),v);AlarmReceiver.scheduleToday(this);tasks();}).setNegativeButton("Cancel",null).show();}
 void health(){LinearLayout x=base("HEALTH COMMAND CENTER","Track trends; the app does not diagnose or change prescriptions.");header(x);Button add=btn("+ Add health measurement / lab result");x.addView(add);add.setOnClickListener(v->editHealth(null));for(Map<String,String>m:s.q("SELECT * FROM health ORDER BY day DESC,id DESC")){LinearLayout c=card();c.addView(t(m.get("metric")+": "+m.get("value")+" "+m.get("unit"),17,true));c.addView(sub(m.get("day")+"  "+m.get("notes")));Button ed=dark("Edit");c.addView(ed);ed.setOnClickListener(v->editHealth(m));x.addView(c);}setContentView(scroll(x));}
 void editHealth(Map<String,String>m){EditText a=e("Metric"),v=e("Value"),u=e("Unit"),d=e("Date YYYY-MM-DD"),n=e("Notes / source");d.setText(LocalDate.now().toString());if(m!=null){a.setText(m.get("metric"));v.setText(m.get("value"));u.setText(m.get("unit"));d.setText(m.get("day"));n.setText(m.get("notes"));}LinearLayout b=base("Health entry",null);for(View z:new View[]{a,v,u,d,n})b.addView(z);new AlertDialog.Builder(this).setTitle("Health entry").setView(scroll(b)).setPositiveButton("Save",(q,w)->{ContentValues c=new ContentValues();c.put("metric",a.getText().toString());c.put("value",v.getText().toString());c.put("unit",u.getText().toString());c.put("day",d.getText().toString());c.put("notes",n.getText().toString());if(m==null)s.insert("health",c);else s.update("health",Long.parseLong(m.get("id")),c);health();}).setNegativeButton("Cancel",null).show();}
 void meds(){LinearLayout x=base("MEDICATIONS","Private list. Never change a dose because of the app.");header(x);Button add=btn("+ Add medicine");x.addView(add);add.setOnClickListener(v->editMed(null));for(Map<String,String>m:s.q("SELECT * FROM medications WHERE active=1 ORDER BY timing")){LinearLayout c=card();c.addView(t(m.get("name")+" — "+m.get("dose"),17,true));c.addView(sub(m.get("timing")+"\n"+m.get("notes")));Button ed=dark("Edit");c.addView(ed);ed.setOnClickListener(v->editMed(m));x.addView(c);}setContentView(scroll(x));}
 void editMed(Map<String,String>m){EditText a=e("Medicine"),d=e("Dose / strength"),ti=e("Timing"),n=e("Notes");if(m!=null){a.setText(m.get("name"));d.setText(m.get("dose"));ti.setText(m.get("timing"));n.setText(m.get("notes"));}LinearLayout b=base("Medicine",null);for(View z:new View[]{a,d,ti,n})b.addView(z);new AlertDialog.Builder(this).setTitle("Medicine").setView(scroll(b)).setPositiveButton("Save",(q,w)->{ContentValues c=new ContentValues();c.put("name",a.getText().toString());c.put("dose",d.getText().toString());c.put("timing",ti.getText().toString());c.put("notes",n.getText().toString());if(m==null)s.insert("medications",c);else s.update("medications",Long.parseLong(m.get("id")),c);meds();}).setNegativeButton("Cancel",null).show();}
 void meals(){LinearLayout x=base("MEALS & SHOPPING","Taste first, but calories, protein and glucose awareness stay visible.");header(x);Button suggest=btn("Suggest a recipe not used in the last 30 days");x.addView(suggest);suggest.setOnClickListener(v->suggestMeal());Button add=dark("+ Add / edit recipes");x.addView(add);add.setOnClickListener(v->recipes());x.addView(t("Shopping List",19,true));Button si=dark("+ Add shopping item");x.addView(si);si.setOnClickListener(v->addShopping());for(Map<String,String>m:s.q("SELECT * FROM shopping ORDER BY category,item")){CheckBox cb=new CheckBox(this);cb.setText(m.get("item")+"  ["+m.get("category")+"]");cb.setTextColor(TEXT);cb.setChecked("1".equals(m.get("bought")));cb.setOnCheckedChangeListener((q,w)->{ContentValues c=new ContentValues();c.put("bought",w?1:0);s.update("shopping",Long.parseLong(m.get("id")),c);});x.addView(cb);}setContentView(scroll(x));}
 void suggestMeal(){LocalDate cut=LocalDate.now().minusDays(30);List<Map<String,String>>r=s.q("SELECT * FROM recipes WHERE active=1 AND (last_used IS NULL OR last_used='' OR last_used<?) ORDER BY RANDOM() LIMIT 1",cut.toString());if(r.isEmpty()){toast("Add more recipes or wait for the 30-day rotation.");return;}Map<String,String>m=r.get(0);new AlertDialog.Builder(this).setTitle(m.get("name")).setMessage(m.get("cuisine")+"\nApprox. "+m.get("calories")+" kcal • "+m.get("protein")+" g protein\n\n"+m.get("details")).setPositiveButton("Use today",(d,w)->{ContentValues c=new ContentValues();c.put("last_used",LocalDate.now().toString());s.update("recipes",Long.parseLong(m.get("id")),c);}).setNegativeButton("Close",null).show();}
 void recipes(){LinearLayout x=base("RECIPES","Exact recipe repeat lock: 30 days.");header(x);Button add=btn("+ Add recipe");x.addView(add);add.setOnClickListener(v->editRecipe(null));for(Map<String,String>m:s.q("SELECT * FROM recipes ORDER BY name")){LinearLayout c=card();c.addView(t(m.get("name"),16,true));c.addView(sub(m.get("cuisine")+" • "+m.get("calories")+" kcal • "+m.get("protein")+"g protein\nLast used: "+m.get("last_used")));Button ed=dark("Edit");c.addView(ed);ed.setOnClickListener(v->editRecipe(m));x.addView(c);}setContentView(scroll(x));}
 void editRecipe(Map<String,String>m){EditText a=e("Recipe name"),cu=e("Cuisine"),k=e("Calories"),p=e("Protein g"),de=e("Ingredients + method");if(m!=null){a.setText(m.get("name"));cu.setText(m.get("cuisine"));k.setText(m.get("calories"));p.setText(m.get("protein"));de.setText(m.get("details"));}LinearLayout b=base("Recipe",null);for(View z:new View[]{a,cu,k,p,de})b.addView(z);new AlertDialog.Builder(this).setTitle("Recipe").setView(scroll(b)).setPositiveButton("Save",(q,w)->{ContentValues c=new ContentValues();c.put("name",a.getText().toString());c.put("cuisine",cu.getText().toString());c.put("calories",parseInt(k.getText().toString(),0));c.put("protein",parseDouble(p.getText().toString(),0));c.put("details",de.getText().toString());if(m==null)s.insert("recipes",c);else s.update("recipes",Long.parseLong(m.get("id")),c);recipes();}).setNegativeButton("Cancel",null).show();}
 void addShopping(){EditText a=e("Item"),c=e("Category");LinearLayout b=base("Shopping item",null);b.addView(a);b.addView(c);new AlertDialog.Builder(this).setTitle("Shopping item").setView(b).setPositiveButton("Add",(d,w)->{ContentValues v=new ContentValues();v.put("item",a.getText().toString());v.put("category",c.getText().toString());s.insert("shopping",v);meals();}).setNegativeButton("Cancel",null).show();}
 void workouts(){LinearLayout x=base("WORKOUTS","Progressive training. High-intensity sessions can be safety-locked.");header(x);boolean cl="true".equals(s.get("medical_clearance_hiit","false"));TextView st=t("HIIT clearance flag: "+(cl?"RECORDED":"NOT RECORDED"),16,true);st.setTextColor(cl?ACC:WARN);x.addView(st);Button flag=dark(cl?"Remove clearance flag":"Record clinician clearance");x.addView(flag);flag.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Medical clearance flag").setMessage("Only record this when vigorous exercise has been cleared appropriately for your health status.").setPositiveButton("Confirm",(d,w)->{s.set("medical_clearance_hiit",cl?"false":"true");workouts();}).setNegativeButton("Cancel",null).show());Button add=btn("+ Add workout");x.addView(add);add.setOnClickListener(v->editWorkout(null));for(Map<String,String>m:s.q("SELECT * FROM workouts WHERE active=1 ORDER BY phase,dow")){LinearLayout c=card();boolean lock="1".equals(m.get("requires_clearance"))&&!cl;c.addView(t((lock?"🔒 ":"")+m.get("name"),16,true));c.addView(sub("Phase "+m.get("phase")+" • Day "+m.get("dow")+" • "+m.get("duration")+" min\n"+m.get("details")));Button start=dark(lock?"Locked":"Start safety check");c.addView(start);start.setEnabled(!lock);if(!lock)start.setOnClickListener(v->workoutGate(m));Button ed=dark("Edit");c.addView(ed);ed.setOnClickListener(v->editWorkout(m));x.addView(c);}setContentView(scroll(x));}
 void workoutGate(Map<String,String>m){EditText g=e("Pre-workout glucose mg/dL (optional)");CheckBox chest=new CheckBox(this);chest.setText("Chest pain / pressure now");chest.setTextColor(TEXT);CheckBox dizzy=new CheckBox(this);dizzy.setText("Dizziness / unusual breathlessness now");dizzy.setTextColor(TEXT);LinearLayout b=base("Workout Safety Gate",null);b.addView(g);b.addView(chest);b.addView(dizzy);new AlertDialog.Builder(this).setTitle(m.get("name")).setView(b).setPositiveButton("Check",(d,w)->{double z=parseDouble(g.getText().toString(),-1);if(chest.isChecked()||dizzy.isChecked()){alert("Do not start","Stop and seek appropriate medical advice; urgent symptoms require urgent care.");return;}if(z>=0&&z<70){alert("Do not start","Low glucose: treat the low glucose according to your medical plan before exercise.");return;}alert("Ready","Safety gate passed. Start gently and stop if you feel unwell.");}).setNegativeButton("Cancel",null).show();}
 void editWorkout(Map<String,String>m){EditText a=e("Workout"),ph=e("Phase"),day=e("Day of week 1–7"),du=e("Duration minutes"),de=e("Details");CheckBox lock=new CheckBox(this);lock.setText("Require clearance");lock.setTextColor(TEXT);if(m!=null){a.setText(m.get("name"));ph.setText(m.get("phase"));day.setText(m.get("dow"));du.setText(m.get("duration"));de.setText(m.get("details"));lock.setChecked("1".equals(m.get("requires_clearance")));}LinearLayout b=base("Workout",null);for(View z:new View[]{a,ph,day,du,de,lock})b.addView(z);new AlertDialog.Builder(this).setTitle("Workout").setView(scroll(b)).setPositiveButton("Save",(q,w)->{ContentValues c=new ContentValues();c.put("name",a.getText().toString());c.put("phase",parseInt(ph.getText().toString(),1));c.put("dow",parseInt(day.getText().toString(),1));c.put("duration",parseInt(du.getText().toString(),30));c.put("details",de.getText().toString());c.put("requires_clearance",lock.isChecked()?1:0);if(m==null)s.insert("workouts",c);else s.update("workouts",Long.parseLong(m.get("id")),c);workouts();}).setNegativeButton("Cancel",null).show();}
 void memories(){LinearLayout x=base("FAMILY MEMORY BOOK","Create at least one small memory often.");header(x);Button add=btn("+ Add memory");x.addView(add);add.setOnClickListener(v->editMemory(null));for(Map<String,String>m:s.q("SELECT * FROM memories ORDER BY day DESC,id DESC")){LinearLayout c=card();c.addView(t(m.get("day")+" — "+m.get("title"),16,true));c.addView(sub(m.get("note")));Button ed=dark("Edit");c.addView(ed);ed.setOnClickListener(v->editMemory(m));x.addView(c);}setContentView(scroll(x));}
 void editMemory(Map<String,String>m){EditText d=e("Date"),a=e("Title"),n=e("What happened?");d.setText(LocalDate.now().toString());if(m!=null){d.setText(m.get("day"));a.setText(m.get("title"));n.setText(m.get("note"));}LinearLayout b=base("Memory",null);for(View z:new View[]{d,a,n})b.addView(z);new AlertDialog.Builder(this).setTitle("Memory").setView(b).setPositiveButton("Save",(q,w)->{ContentValues c=new ContentValues();c.put("day",d.getText().toString());c.put("title",a.getText().toString());c.put("note",n.getText().toString());if(m==null)s.insert("memories",c);else s.update("memories",Long.parseLong(m.get("id")),c);memories();}).setNegativeButton("Cancel",null).show();}
 void workMoney(){LinearLayout x=base("WORK & MONEY","Focus on the next action, not an endless list.");header(x);x.addView(t("Projects",19,true));Button ap=btn("+ Add project");x.addView(ap);ap.setOnClickListener(v->editProject(null));for(Map<String,String>m:s.q("SELECT * FROM projects ORDER BY priority DESC")){LinearLayout c=card();c.addView(t(m.get("name"),16,true));c.addView(sub("Priority "+m.get("priority")+" • "+m.get("status")+"\nNext: "+m.get("next_action")));Button ed=dark("Edit");c.addView(ed);ed.setOnClickListener(v->editProject(m));x.addView(c);}x.addView(t("Money",19,true));Button tx=dark("+ Add income / expense");x.addView(tx);tx.setOnClickListener(v->editTx());double in=0,out=0;for(Map<String,String>m:s.q("SELECT * FROM finance ORDER BY day DESC,id DESC")){double a=parseDouble(m.get("amount"),0);if("INCOME".equalsIgnoreCase(m.get("type")))in+=a;else out+=a;LinearLayout c=card();c.addView(t(m.get("type")+"  Rs "+String.format(Locale.US,"%.2f",a),16,true));c.addView(sub(m.get("day")+" • "+m.get("category")+" • "+m.get("note")));x.addView(c);}x.addView(t("Net recorded: Rs "+String.format(Locale.US,"%.2f",in-out),18,true));setContentView(scroll(x));}
 void editProject(Map<String,String>m){EditText a=e("Project"),p=e("Priority 1–5"),n=e("Next action"),st=e("Status");if(m!=null){a.setText(m.get("name"));p.setText(m.get("priority"));n.setText(m.get("next_action"));st.setText(m.get("status"));}else st.setText("ACTIVE");LinearLayout b=base("Project",null);for(View z:new View[]{a,p,n,st})b.addView(z);new AlertDialog.Builder(this).setTitle("Project").setView(b).setPositiveButton("Save",(q,w)->{ContentValues c=new ContentValues();c.put("name",a.getText().toString());c.put("priority",parseInt(p.getText().toString(),3));c.put("next_action",n.getText().toString());c.put("status",st.getText().toString());if(m==null)s.insert("projects",c);else s.update("projects",Long.parseLong(m.get("id")),c);workMoney();}).setNegativeButton("Cancel",null).show();}
 void editTx(){EditText d=e("Date"),ty=e("INCOME or EXPENSE"),ca=e("Category"),a=e("Amount"),n=e("Note");d.setText(LocalDate.now().toString());LinearLayout b=base("Transaction",null);for(View z:new View[]{d,ty,ca,a,n})b.addView(z);new AlertDialog.Builder(this).setTitle("Transaction").setView(b).setPositiveButton("Save",(q,w)->{ContentValues c=new ContentValues();c.put("day",d.getText().toString());c.put("type",ty.getText().toString().toUpperCase(Locale.ROOT));c.put("category",ca.getText().toString());c.put("amount",parseDouble(a.getText().toString(),0));c.put("note",n.getText().toString());s.insert("finance",c);workMoney();}).setNegativeButton("Cancel",null).show();}
 void rewards(){LinearLayout x=base("REWARDS & CONSEQUENCES","Strict enough to matter; never physically harmful.");header(x);x.addView(t("Life Points today: "+todayScore(),22,true));x.addView(t("Family Memory Fund penalties",18,true));x.addView(sub("Today: Rs "+penaltiesToday()+" / "+s.get("daily_penalty_cap","500")+"\nThis week: Rs "+penaltiesWeek()+" / "+s.get("weekly_penalty_cap","2000")));for(Map<String,String>m:s.q("SELECT * FROM penalties ORDER BY day DESC,id DESC")){LinearLayout c=card();c.addView(t("Rs "+m.get("amount")+" — "+m.get("reason"),15,true));c.addView(sub(m.get("day")));x.addView(c);}x.addView(sub("Suggested reward ladder: movie/gaming → restaurant → spending money → gadget → family trip. Edit your caps in Settings."));setContentView(scroll(x));}
 void calendar(){LinearLayout x=base("CALENDAR","Uses the phone's Calendar Provider. If your Google account syncs to the phone, Life OS can write to that calendar.");header(x);Button choose=btn("Select Google / device calendar");x.addView(choose);choose.setOnClickListener(v->chooseCalendar());x.addView(sub("Selected calendar ID: "+s.get("calendar_id","none")));Button sync=dark("Sync today's marked tasks now");x.addView(sync);sync.setOnClickListener(v->syncTodayCalendar());setContentView(scroll(x));}
 void chooseCalendar(){if(checkSelfPermission(Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED){requestBasics();return;}ArrayList<String>names=new ArrayList<>(),ids=new ArrayList<>();try(Cursor c=getContentResolver().query(CalendarContract.Calendars.CONTENT_URI,new String[]{CalendarContract.Calendars._ID,CalendarContract.Calendars.CALENDAR_DISPLAY_NAME,CalendarContract.Calendars.ACCOUNT_NAME},CalendarContract.Calendars.VISIBLE+"=1",null,null)){while(c!=null&&c.moveToNext()){ids.add(c.getString(0));names.add(c.getString(1)+" — "+c.getString(2));}}catch(Exception e){toast("Unable to read calendars");return;}new AlertDialog.Builder(this).setTitle("Choose calendar").setItems(names.toArray(new String[0]),(d,w)->{s.set("calendar_id",ids.get(w));calendar();}).show();}
 void syncTodayCalendar(){if(checkSelfPermission(Manifest.permission.WRITE_CALENDAR)!=PackageManager.PERMISSION_GRANTED){requestBasics();return;}long cal;try{cal=Long.parseLong(s.get("calendar_id",""));}catch(Exception e){toast("Select a calendar first");return;}int count=0;for(Map<String,String>m:s.q("SELECT * FROM tasks WHERE active=1 AND calendar_sync=1")){if(!dayMatch(m.get("days")))continue;try{int min=Integer.parseInt(m.get("start_min")),dur=Integer.parseInt(m.get("duration"));ZonedDateTime z=LocalDate.now().atTime(min/60,min%60).atZone(ZoneId.systemDefault());ContentValues v=new ContentValues();v.put(CalendarContract.Events.DTSTART,z.toInstant().toEpochMilli());v.put(CalendarContract.Events.DTEND,z.plusMinutes(dur).toInstant().toEpochMilli());v.put(CalendarContract.Events.TITLE,"SECRET".equals(m.get("privacy"))?"Life OS Private Task":m.get("title"));v.put(CalendarContract.Events.DESCRIPTION,"Created by Suresh Life OS");v.put(CalendarContract.Events.CALENDAR_ID,cal);v.put(CalendarContract.Events.EVENT_TIMEZONE,ZoneId.systemDefault().getId());getContentResolver().insert(CalendarContract.Events.CONTENT_URI,v);count++;}catch(Exception ignored){}}toast("Synced "+count+" task(s)");}
 void backup(){LinearLayout x=base("ENCRYPTED BACKUP","Save to Google Drive through Android's document picker. The backup contains private data.");header(x);Button ex=btn("Create encrypted backup");Button im=dark("Restore encrypted backup / private setup");x.addView(ex);x.addView(im);ex.setOnClickListener(v->askBackup(true));im.setOnClickListener(v->askBackup(false));setContentView(scroll(x));}
 void askBackup(boolean save){EditText p=e("Backup password (minimum 6 characters)");p.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);new AlertDialog.Builder(this).setTitle(save?"Encrypt backup":"Decrypt backup").setView(p).setPositiveButton("Continue",(d,w)->{backupPassword=p.getText().toString();if(backupPassword.length()<6){toast("Password too short");return;}Intent i=new Intent(save?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);if(save)i.putExtra(Intent.EXTRA_TITLE,"SureshLifeOS-"+LocalDate.now()+".lifeos");startActivityForResult(i,save?SAVE:OPEN);}).setNegativeButton("Cancel",null).show();}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null||data.getData()==null)return;try{Uri u=data.getData();if(req==SAVE){String enc=Crypto.enc(s.exportJson(),backupPassword);try(OutputStream o=getContentResolver().openOutputStream(u,"w")){o.write(enc.getBytes(StandardCharsets.UTF_8));}toast("Encrypted backup saved");}else if(req==OPEN){String blob;try(InputStream in=getContentResolver().openInputStream(u);ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[8192];int n;while((n=in.read(b))>0)o.write(b,0,n);blob=o.toString("UTF-8");}s.importJson(Crypto.dec(blob,backupPassword));AlarmReceiver.scheduleToday(this);toast("Private setup restored");home();}}catch(Exception e){alert("Backup error",e.getMessage()==null?"Unable to process backup":e.getMessage());}backupPassword="";}
 void settings(){LinearLayout x=base("SETTINGS","All important values can be changed later without rebuilding the APK.");header(x);String[]keys={"profile_name","height_cm","weight_kg","waist_cm","target_sleep","target_wake","eating_start","eating_end","coffee_count","coffee_sugar_tsp_each","coffee_milk_grams_each","coffee_milk_kcal_per_100g","daily_calorie_target","protein_target_g","daily_penalty_cap","weekly_penalty_cap","glibenclamide_strength","bco_composition"};for(String k:keys){LinearLayout c=card();c.addView(t(k.replace('_',' ').toUpperCase(Locale.ROOT),13,true));TextView val=t(s.get(k,"UNSET"),16,false);c.addView(val);c.setOnClickListener(v->editSetting(k));x.addView(c);}Button pin=dark("Change PIN");x.addView(pin);pin.setOnClickListener(v->{s.set("pin_hash","");unlocked=false;showLock();});x.addView(sub("Private notifications intentionally never reveal the actual task on the lock screen or notification shade."));setContentView(scroll(x));}
 void editSetting(String k){EditText v=e(k);v.setText(s.get(k,""));new AlertDialog.Builder(this).setTitle(k.replace('_',' ')).setView(v).setPositiveButton("Save",(d,w)->{s.set(k,v.getText().toString());settings();}).setNegativeButton("Cancel",null).show();}
 void alert(String title,String msg){new AlertDialog.Builder(this).setTitle(title).setMessage(msg).setPositiveButton("OK",null).show();} void toast(String x){Toast.makeText(this,x,Toast.LENGTH_SHORT).show();} int parseInt(String x,int d){try{return Integer.parseInt(x);}catch(Exception e){return d;}} double parseDouble(String x,double d){try{return Double.parseDouble(x);}catch(Exception e){return d;}}
 @Override public void onBackPressed(){if(unlocked)home();else super.onBackPressed();}
}
